mapper.select:
select vph.*

    ,vi.video_name, vi.video_cover

from pilipili.video_play_history vph

    left join pilipili.video_info vi on vph.video_id = vi.video_id

where vph.user_id = #{userId}
order by ${orderByField}

mapper.delete:
delete from pilipili.video_play_history
where user_id = #{userId}

    and video_id = #{videoId}

mapper.select:
select video_id
from pilipili.video_play_history
where user_id = #{userId}

select count(*)
from pilipili.video_play_history
where user_id = #{userId} and video_id = #{videoId}
